import{c as a,Q as s,j as t,m as i}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Increase PHP Max Input Vars","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/increase-php-max-input-vars.md","filePath":"how-to/increase-php-max-input-vars.md"}'),o={name:"how-to/increase-php-max-input-vars.md"};function n(r,e,h,l,p,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="increase-php-max-input-vars" tabindex="-1">Increase PHP Max Input Vars <a class="header-anchor" href="#increase-php-max-input-vars" aria-label="Permalink to &quot;Increase PHP Max Input Vars&quot;">​</a></h1><p>The PHP Max Input Vars setting defines the maximum number of variables your server can use for a single function. For modern WordPress themes this value should be set to at least <strong>3000</strong>. Lower values can cause lost data in Theme Options, disappearing widgets, and <a href="https://wordpress.org/support/topic/menu-item-limit-1/" target="_blank" rel="noreferrer">menu items not saving</a>.</p><h2 id="method-1-edit-php-ini" tabindex="-1">Method 1: Edit php.ini <a class="header-anchor" href="#method-1-edit-php-ini" aria-label="Permalink to &quot;Method 1: Edit php.ini&quot;">​</a></h2><blockquote><p><strong>Note:</strong> Many shared hosts prohibit direct access to <code>php.ini</code>. Only use this method if you have direct access, or are on a local server.</p></blockquote><ol><li>Locate your <code>php.ini</code> file. If you can&#39;t find it, create one in the root folder of your WordPress installation.</li><li>Find or add the following line and set it to 3000:</li></ol><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_input_vars</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 3000</span></span></code></pre></div><ol start="3"><li>Save the file and restart your server.</li></ol><h2 id="method-2-edit-htaccess" tabindex="-1">Method 2: Edit .htaccess <a class="header-anchor" href="#method-2-edit-htaccess" aria-label="Permalink to &quot;Method 2: Edit .htaccess&quot;">​</a></h2><blockquote><p><strong>Note:</strong> Back up your <code>.htaccess</code> file before editing.</p></blockquote><ol><li>Locate your <code>.htaccess</code> file in the root of your WordPress installation (it may be hidden — enable hidden files in your file manager or FTP client).</li><li>Add the following line:</li></ol><div class="language-apache vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">apache</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">php_value</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> max_input_vars</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000</span></span></code></pre></div><p>If your server has the Suhosin security patch, use these instead:</p><div class="language-apache vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">apache</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">php_value</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> suhosin.request.max_vars</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">php_value</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> suhosin.post.max_vars</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000</span></span></code></pre></div><ol start="3"><li>Save the file and refresh your website.</li></ol><h2 id="contact-your-host" tabindex="-1">Contact Your Host <a class="header-anchor" href="#contact-your-host" aria-label="Permalink to &quot;Contact Your Host&quot;">​</a></h2><p>If neither method works, contact your host and ask them to increase <code>max_input_vars</code> to 3000. Most shared hosts can do this on request.</p>`,16)])])}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
